// Format Building Response for Telegram
const input = $input.first().json;

console.log('=== FORMAT BUILDING RESPONSE ===');
console.log('Smart AI Response:', JSON.stringify(input, null, 2));

// Get conversation data from Execute Building Plan node
const conversationData = $('Webhook').first().json.body;
console.log('Retrieved conversation data', {
      chatId: conversationData.chatId,
      playerName: conversationData.playerName,
      source: conversationData.username
    });

// Parse smart AI API response
const apiSuccess = input.success || false;
const userMessage = input.userMessage || '';
const executionResult = input.executionResult || 'No execution details';
const apiMessage = input.message || '';

// Create formatted response message
let responseMessage = '';
if (apiSuccess) {
  // Check if the AI provided clarification or alternative suggestions
  if (executionResult.toLowerCase().includes('not possible') || 
      executionResult.toLowerCase().includes('alternative') ||
      executionResult.toLowerCase().includes('instead')) {
    responseMessage = ` **Smart AI Response**\n\n` +
                     ` **Your Request:** ${userMessage.substring(0, 100)}${userMessage.length > 100 ? '...' : ''}\n\n` +
                     ` **AI Analysis:** ${executionResult.substring(0, 300)}${executionResult.length > 300 ? '...' : ''}\n\n` +
                     ` The AI has analyzed your request and provided intelligent feedback!`;
  } else {
    responseMessage = ` **Building Task Completed!**\n\n` +
                     ` **Request:** ${userMessage.substring(0, 100)}${userMessage.length > 100 ? '...' : ''}\n\n` +
                     ` **Status:** ${apiMessage}\n\n` +
                     ` **AI Execution:** ${executionResult.substring(0, 200)}${executionResult.length > 200 ? '...' : ''}\n\n` +
                     ` The smart AI successfully processed your building request!`;
  }
} else {
  const errorMessage = input.error || input.details || 'Unknown error occurred';
  responseMessage = ` **Building Task Failed**\n\n` +
                   ` **Request:** ${userMessage.substring(0, 100)}${userMessage.length > 100 ? '...' : ''}\n\n` +
                   ` **Error:** ${errorMessage}\n\n`;

  if (executionResult && executionResult !== 'No execution details') {
    responseMessage += ` **AI Response:** ${executionResult.substring(0, 200)}${executionResult.length > 200 ? '...' : ''}\n\n`;
  }

  responseMessage += ` **Tip:** The AI might have suggestions or alternatives. Check the response above!`;
}

console.log('Formatted response:', responseMessage);

// Extract code output between "Code Output" and "Code finished"
let ai_actions = '';
const codeOutputMatch = apiMessage.match(/Code Output([\s\S]*?)Code finished/i);
if (codeOutputMatch && codeOutputMatch[1]) {
  ai_actions = codeOutputMatch[1].trim();
  console.log('Extracted code output:', ai_actions);
} else {
  console.log('No code output found between markers');
}

// Return formatted response with conversation data for Telegram
return {
  json: {
    chatId: conversationData.chatId || input.chatId || 'unknown',
    text: responseMessage,
    playerName: conversationData.playerName || 'User',
    source: conversationData.source || 'telegram',
    conversationHistory: conversationData.conversationHistory || [],
    executionResult: {
      type: 'smart_ai_building',
      success: apiSuccess,
      response: responseMessage,
      apiResult: input,
      aiResponse: executionResult,
      aiActions: ai_actions
    }
  }
};

