    } else {
      // Try to find raw JSON object/array pattern
      const jsonMatch = outputString.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);

      if (jsonMatch) {
        console.log('✓ Extracted JSON pattern');
        parsedData = JSON.parse(jsonMatch[1]);
      } else {
        throw new Error('No JSON found in output');
      }
    }
  }

  console.log('Parsed successfully');
  console.log('Validation Result:', parsedData.validationResult);
  console.log('Failed Checks:', parsedData.failedChecks?.length || 0);

  // Return the parsed validation report
  return [{
    json: {
      validationReport: parsedData,
      success: true,
      parseMethod: 'code-block-extraction'
    }
  }];

} catch (error) {
  console.error('Error parsing JSON:', error.message);

  return [{
    json: {
      error: 'Failed to parse validation report',
      message: error.message,
      rawOutputPreview: outputString.substring(0, 300) + '...',
      success: false
    }
  }];
}

